import {expandScenarioText} from './scenario-text.js?v=civic-inspection-1';
export const DEFAULT_BRIEFING='A challenge created from your city. City-file exports preserve its goals, deadline and current progress.';
export function validateScenarioStory(v){return Object.fromEntries(['briefing','winMessage','lossMessage'].map(key=>{const value=v[key]===undefined?'':v[key];if(typeof value!=='string'||value.length>1500||/[\x00-\x08\x0b\x0c\x0e-\x1f]/.test(value))throw Error('Scenario messages must be plain text, up to 1,500 characters each.');return[key,value.trim()];}));}
const escapeText=value=>value.replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
export function scenarioStory(s,c=null){if(s.id!=='custom')return'';const d=s.definition,ending=s.status==='won'?d.winMessage:s.status==='lost'?d.lossMessage:'';return `<details><summary>Scenario variables</summary><dl>${(d.variables||[]).map((v,i)=>`<dt>${escapeText(v.name)} · variable${i+1}</dt><dd>${(s.variables?.[i]??v.initial).toLocaleString()}</dd>`).join('')}</dl></details><h3>Briefing</h3><p style="white-space:pre-wrap">${escapeText(expandScenarioText(d.briefing||DEFAULT_BRIEFING,c))}</p>${ending?`<h3>${s.status==='won'?'Success':'Challenge ended'}</h3><p style="white-space:pre-wrap">${escapeText(expandScenarioText(ending,c))}</p>`:''}`;}
